 static final class Memory implements SharedPreferences {
  final Map<String,Object> values=new HashMap<>();final Map<String,Object> disk;final List<OnSharedPreferenceChangeListener> listeners=new ArrayList<>();int commits,editors;boolean fail,failEdit,throwCommit,skipDisk,failGetAll;Runnable beforeRead,afterCommit;
  Memory(Map<String,Object> disk){this.disk=disk;values.putAll(disk);}
  public Map<String,?> getAll(){if(beforeRead!=null)beforeRead.run();if(failGetAll)throw new IllegalStateException("synthetic read failure");return new HashMap<>(values);}public String getString(String k,String d){Object x=values.get(k);return x==null?d:(String)x;}public int getInt(String k,int d){Object x=values.get(k);return x==null?d:(Integer)x;}public long getLong(String k,long d){Object x=values.get(k);return x==null?d:(Long)x;}public float getFloat(String k,float d){Object x=values.get(k);return x==null?d:(Float)x;}public boolean getBoolean(String k,boolean d){Object x=values.get(k);return x==null?d:(Boolean)x;}@SuppressWarnings("unchecked") public Set<String> getStringSet(String k,Set<String>d){Object x=values.get(k);return x==null?d:(Set<String>)x;}public boolean contains(String k){return values.containsKey(k);}public void registerOnSharedPreferenceChangeListener(OnSharedPreferenceChangeListener x){listeners.add(x);}public void unregisterOnSharedPreferenceChangeListener(OnSharedPreferenceChangeListener x){listeners.remove(x);}
  public Editor edit(){editors++;if(failEdit)throw new IllegalStateException("synthetic editor failure");return new Editor(){Map<String,Object> puts=new HashMap<>();boolean clear;public Editor putString(String k,String x){puts.put(k,x);return this;}public Editor putStringSet(String k,Set<String>x){puts.put(k,x==null?null:new HashSet<>(x));return this;}public Editor putInt(String k,int x){puts.put(k,x);return this;}public Editor putLong(String k,long x){puts.put(k,x);return this;}public Editor putFloat(String k,float x){puts.put(k,x);return this;}public Editor putBoolean(String k,boolean x){puts.put(k,x);return this;}public Editor remove(String k){puts.put(k,null);return this;}public Editor clear(){clear=true;return this;}public boolean commit(){commits++;if(clear)values.clear();for(Map.Entry<String,Object>e:puts.entrySet())if(e.getValue()==null)values.remove(e.getKey());else values.put(e.getKey(),e.getValue());boolean ok=!fail;if(ok&&!skipDisk){disk.clear();disk.putAll(values);}if(afterCommit!=null)afterCommit.run();if(throwCommit)throw new IllegalStateException("synthetic unconfirmed commit");for(String k:puts.keySet())for(OnSharedPreferenceChangeListener l:new ArrayList<>(listeners))l.onSharedPreferenceChanged(Memory.this,k);return ok;}public void apply(){commit();}};}
 }
 static final class Owner extends Context {
  static final Map<Map<String,Map<String,Object>>,File> DIRECTORIES=new IdentityHashMap<>();
  final Map<String,Map<String,Object>> disk;final Map<String,Memory> memory=new HashMap<>();final File directory;Owner(){this(new HashMap<>());}Owner(Map<String,Map<String,Object>> disk){this.disk=disk;try{File prior=DIRECTORIES.get(disk);directory=prior==null?java.nio.file.Files.createTempDirectory("wangshu-settings-owner-").toFile():prior;DIRECTORIES.put(disk,directory);}catch(IOException error){throw new UncheckedIOException(error);}}
  public File getFilesDir(){return directory;}public File getDataDir(){return directory;}
  public Memory getSharedPreferences(String name,int mode){return memory.computeIfAbsent(name,key->new Memory(disk.computeIfAbsent(key,k->new HashMap<>())));}
 }
 static Map<SettingsBackup.Key,Object> custom(Owner c)throws Exception{return SettingsBackup.decode(SettingsBackup.encode(key->key.name.equals("candidateFontDelta")?3:key.name.equals("phraseEnglish")?true:key.fallback));}
 public static void main(String[] args)throws Exception{
  Owner c=new Owner();Memory oldKeyboard=c.getSharedPreferences("keyboard",0),oldClipboard=c.getSharedPreferences("clipboard",0),oldLearning=c.getSharedPreferences("candidate-learning",0);
  oldKeyboard.edit().putInt("cursorStepDp",23).putString("customFutureKey","kept").commit();oldClipboard.edit().putBoolean("enabled",true).putInt("days",30).commit();oldLearning.edit().putBoolean("enabled",true).commit();
  Map<String,?> oldK=oldKeyboard.getAll(),oldC=oldClipboard.getAll();SharedPreferences keyboard=AppPreferences.open(c,"keyboard"),clipboard=AppPreferences.open(c,"clipboard");
  require(keyboard.getInt("cursorStepDp",16)==23,"legacy migrated");require(keyboard.getString("customFutureKey",null).equals("kept"),"unknown key retained");require(clipboard.getBoolean("enabled",false),"existing capture optin preserved");require(oldKeyboard.getAll().equals(oldK)&&oldClipboard.getAll().equals(oldC),"legacy files unchanged");
  require(AppPreferences.open(c,"candidate-learning").getBoolean("enabled",false),"learning optin retained");
  List<String> events=new ArrayList<>();SharedPreferences.OnSharedPreferenceChangeListener listener=(prefs,key)->events.add(key);keyboard.registerOnSharedPreferenceChangeListener(listener);keyboard.edit().putInt("candidateFontDelta",1).commit();clipboard.edit().putInt("days",7).commit();require(events.equals(Arrays.asList("candidateFontDelta")),"listener group keys and isolation");keyboard.unregisterOnSharedPreferenceChangeListener(listener);keyboard.edit().putInt("candidateFontDelta",2).commit();require(events.size()==1,"listener unregistered");
  byte[] before=AppPreferences.snapshot(c);Map<SettingsBackup.Key,Object> incoming=custom(c);Memory unified=c.getSharedPreferences(AppPreferences.FILE,0);int count=unified.commits;AppPreferences.restore(c,before,incoming);require(unified.commits==count+1,"all groups one commit");require(keyboard.getInt("candidateFontDelta",0)==3&&AppPreferences.open(c,"associations").getBoolean("phraseEnglish",false),"both groups restored");require(clipboard.getBoolean("enabled",false)&&AppPreferences.open(c,"candidate-learning").getBoolean("enabled",false),"capture/learning flags untouched by restore");require(keyboard.getString("customFutureKey",null).equals("kept"),"future key retained by restore");
  byte[] stale=AppPreferences.snapshot(c);keyboard.edit().putInt("cursorStepDp",24).commit();count=unified.commits;try{AppPreferences.restore(c,stale,incoming);throw new AssertionError("stale accepted");}catch(IOException expected){assertions++;}require(unified.commits==count,"stale restore no commit");
  byte[] raceBefore=AppPreferences.snapshot(c);Thread other=new Thread(()->keyboard.edit().putInt("cursorStepDp",25).commit());other.start();other.join();try{AppPreferences.restore(c,raceBefore,incoming);throw new AssertionError("race accepted");}catch(IOException expected){assertions++;}require(keyboard.getInt("cursorStepDp",0)==25,"concurrent completed edit retained");
  byte[] failureBefore=AppPreferences.snapshot(c);Map<String,Object> diskBefore=new HashMap<>(unified.disk);Map<SettingsBackup.Key,Object> failureIncoming=SettingsBackup.decode(SettingsBackup.encode(key->key.name.equals("candidateFontDelta")?-3:key.name.equals("phraseEnglish")?false:key.fallback));unified.fail=true;
  try{AppPreferences.restore(c,failureBefore,failureIncoming);throw new AssertionError("failure accepted");}catch(IOException expected){require(expected.getMessage().contains("未确认"),"uncertain outcome surfaced");}require(unified.disk.equals(diskBefore),"failed single transaction leaves old whole disk model");require(keyboard.getInt("candidateFontDelta",0)==-3,"failed commit may update process memory as disclosed");
  Owner reopened=new Owner(c.disk);require(AppPreferences.open(reopened,"keyboard").getInt("candidateFontDelta",0)==3&&AppPreferences.open(reopened,"associations").getBoolean("phraseEnglish",false),"restart old whole snapshot no mixed groups");
  unified.fail=false;keyboard.edit().putString("afterFailure","synthetic").commit();require(unified.disk.get("keyboard:candidateFontDelta").equals(-3)&&unified.disk.get("associations:phraseEnglish").equals(false),"later unrelated successful commit may persist earlier unconfirmed memory; no rollback claim");
  SharedPreferences rkey=AppPreferences.open(reopened,"keyboard"),rclip=AppPreferences.open(reopened,"clipboard");rkey.edit().clear().putString("only","new").commit();require(rkey.getAll().size()==1&&rclip.getBoolean("enabled",false),"clear restricted to group");
  Set<String> set=new HashSet<>(Arrays.asList("a"));rkey.edit().putStringSet("set",set).commit();set.add("b");require(rkey.getStringSet("set",null).size()==1,"set write defensive");Set<String> got=rkey.getStringSet("set",null);got.add("c");require(rkey.getStringSet("set",null).size()==1,"set read defensive");
  Owner bad=new Owner();bad.getSharedPreferences("keyboard",0).edit().putInt("cursorStepDp",31).commit();bad.getSharedPreferences(AppPreferences.FILE,0).fail=true;SharedPreferences badKey=AppPreferences.open(bad,"keyboard");require(badKey.getInt("cursorStepDp",16)==16,"failed migration returns safe defaults");require(!badKey.edit().putInt("cursorStepDp",32).commit()&&bad.getSharedPreferences("keyboard",0).getInt("cursorStepDp",0)==31,"failed migration refuses modifications");try{AppPreferences.snapshot(bad);throw new AssertionError("bad migration backed up");}catch(IOException expected){assertions++;}
  require(AppPreferences.managed("keyboard")&&!AppPreferences.managed("unknown-platform-setting"),"framework groups not intercepted");
  Owner reuseOwner=new Owner();SharedPreferences reuse=AppPreferences.open(reuseOwner,"keyboard");
  SharedPreferences.Editor putOnce=reuse.edit().putInt("i",1);putOnce.commit();reuse.edit().putInt("i",2).commit();putOnce.commit();require(reuse.getInt("i",0)==2,"reused editor does not replay committed put");
  SharedPreferences.Editor removeOnce=reuse.edit().remove("i");removeOnce.commit();reuse.edit().putInt("i",3).commit();removeOnce.commit();require(reuse.getInt("i",0)==3,"reused editor does not replay committed remove");
  SharedPreferences.Editor clearOnce=reuse.edit().clear();clearOnce.commit();reuse.edit().putInt("i",4).commit();clearOnce.commit();require(reuse.getInt("i",0)==4,"reused editor does not replay committed group clear");
  SharedPreferences.Editor applyOnce=reuse.edit().putInt("i",5);applyOnce.apply();reuse.edit().putInt("i",6).apply();applyOnce.apply();require(reuse.getInt("i",0)==6,"reused editor does not replay applied put");
  Memory reuseFile=reuseOwner.getSharedPreferences(AppPreferences.FILE,0);reuseFile.fail=true;SharedPreferences.Editor failedOnce=reuse.edit().putInt("i",7);require(!failedOnce.commit(),"failed reused editor first commit remains false");reuseFile.fail=false;reuse.edit().putInt("i",8).commit();failedOnce.commit();require(reuse.getInt("i",0)==8,"failed commit also consumes editor staging");
  Owner damaged=new Owner();damaged.getSharedPreferences("clipboard",0).edit().putBoolean("enabled",true).commit();damaged.getSharedPreferences("candidate-learning",0).edit().putBoolean("enabled",true).commit();
  SharedPreferences dclip=AppPreferences.open(damaged,"clipboard"),dlearn=AppPreferences.open(damaged,"candidate-learning");dclip.edit().putBoolean("enabled",false).commit();dlearn.edit().putBoolean("enabled",false).commit();require(!dclip.getBoolean("enabled",true)&&!dlearn.getBoolean("enabled",true),"capture consent disabled before damage");
  damaged.disk.get(AppPreferences.FILE).clear();Owner missing=new Owner(damaged.disk);require(!AppPreferences.open(missing,"clipboard").getBoolean("enabled",false)&&!AppPreferences.open(missing,"candidate-learning").getBoolean("enabled",false),"missing unified file never reimports retained legacy consent");require(!AppPreferences.open(missing,"clipboard").edit().putBoolean("enabled",true).commit(),"missing unified marker blocks writes");try{AppPreferences.snapshot(missing);throw new AssertionError("damaged store backed up");}catch(IOException expected){assertions++;}
  Owner corrupt=new Owner();corrupt.getSharedPreferences("clipboard",0).edit().putBoolean("enabled",true).commit();File xmlFolder=new File(corrupt.getDataDir(),"shared_prefs");require(xmlFolder.mkdir(),"synthetic XML folder created");java.nio.file.Files.writeString(new File(xmlFolder,AppPreferences.FILE+".xml").toPath(),"synthetic-corrupt-XML");require(!AppPreferences.open(corrupt,"clipboard").getBoolean("enabled",false),"existing unparsed XML without marker fails closed");
  Owner interrupted=new Owner();interrupted.getSharedPreferences("clipboard",0).edit().putBoolean("enabled",true).commit();java.nio.file.Files.writeString(new File(interrupted.getFilesDir(),AppPreferences.FILE+".migration-attempted").toPath(),"synthetic interrupted attempt");require(!AppPreferences.open(interrupted,"clipboard").getBoolean("enabled",false),"interrupted first migration never reimports legacy consent");
  System.out.println("PASS AppPreferences: "+assertions+" assertions; actual adapter, "+(System.getProperty("wangshu.hostTest.directorySync")==null?"production directory sync":"SYNTHETIC directory-sync acknowledgements")+"; synthetic SharedPreferences/context/disk model; Android atomic-file/runtime NOT_RUN");
 }
